    "build": "node scripts/build.mjs",
    "verify-bundle": "node scripts/verify-bundle.mjs",
    "smoke": "node scripts/smoke-test.mjs",
    "test": "node scripts/test.mjs"
  },
  "dependencies": {
    "@modelcontextprotocol/server": "2.0.0-beta.4"
  },
  "devDependencies": {
    "esbuild": "0.28.1"
  }
}

