#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { readdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..', '..');
const localRoot = path.resolve(__dirname, '..');

async function discoverTestFiles(startDir) {
  const results = [];
  async function walk(dir) {
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (entry.name === 'node_modules' || entry.name === '.git') continue;
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(fullPath);
      } else if (entry.isFile() && entry.name.endsWith('.test.ts')) {
        results.push(fullPath);
      }
    }
  }
  await walk(startDir);
  return results;
}

async function main() {
  const arg = process.argv[2];
  let targets;

  if (arg) {
    const resolved = path.resolve(repoRoot, arg);
    const { statSync } = await import('node:fs');
    const stat = statSync(resolved);
    targets = stat.isDirectory() ? await discoverTestFiles(resolved) : [resolved];
  } else {
    targets = await discoverTestFiles(localRoot);
  }

  if (targets.length === 0) {
    console.log('No *.test.ts files found.');
    process.exit(0);
  }

  const child = spawn(
    process.execPath,
    ['--test', '--test-reporter=spec', '--no-warnings=MODULE_TYPELESS_PACKAGE_JSON', ...targets],
    { cwd: repoRoot, stdio: 'inherit' }
  );

  child.on('exit', (code) => {
    process.exit(code ?? 1);
  });
}

main();

